import{_ as t,o as a,c as n,j as e,a as o,aa as r}from"./chunks/framework.BAs_AphD.js";const s="/buildary-help-preview/media/en/diary/en_stazenikpodpisu.jpg",l="/buildary-help-preview/media/en/diary/en_stazenikpodpisu2.jpg",d="/buildary-help-preview/media/en/diary/en_podepisovani1.jpg",p="/buildary-help-preview/media/en/diary/en_podepisovani3.jpg",c="/buildary-help-preview/media/en/diary/en_podepisovani4.jpg",g="/buildary-help-preview/media/en/diary/en_podepisovani6.jpg",h="/buildary-help-preview/media/en/diary/en_podepisovani5.jpg",k=JSON.parse('{"title":"Signing in an External Application","description":"","frontmatter":{"title":"Signing in an External Application","wiki":"en:diary:externalappsignature"},"headers":[],"relativePath":"en/diary/externalappsignature.md","filePath":"en/diary/externalappsignature.md","lastUpdated":1794388980000}'),u={name:"en/diary/externalappsignature.md"};function y(m,i,f,b,w,_){return a(),n("div",null,[...i[0]||(i[0]=[e("h1",{id:"signing-in-an-external-application",tabindex:"-1"},[o("Signing in an External Application "),e("a",{class:"header-anchor",href:"#signing-in-an-external-application","aria-label":'Permalink to "Signing in an External Application"'},"​")],-1),e("figure",{class:"shot",style:{"--w":"600px"}},[e("div",{class:"video"},[e("iframe",{src:"https://www.youtube-nocookie.com/embed/gJc9kiJu69U",title:"YouTube video",loading:"lazy",allowfullscreen:"",allow:"accelerometer; encrypted-media; gyroscope; picture-in-picture"})])],-1),r('<p>The signature is created outside the Buildary application, for example in Adobe Acrobat Reader or PDF-XChange Editor. From the user&#39;s perspective, this is the most labor-intensive of all signing methods offered by Buildary.online. In the past, this was the only signing option available in the Buildary web application. Since version 4.0, significantly more user-friendly signing methods have been available. Therefore, there should be a specific reason for choosing this option.</p><p>With this setting enabled, the application displays the <strong>Download for electronic signing</strong> button instead of the <strong>Sign</strong> button. This downloads the PDF file to your computer or mobile device. You then sign the file in an external application, such as Adobe Acrobat Reader. The signed file is then uploaded back to Buildary using the <strong>Upload signed file</strong> button.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>The type and legal status of the signature created using this procedure depend on the certificate you use.</p></div><p>Before downloading a report for signing, we recommend reviewing the data directly in Buildary and resolving any discrepancies. Only download the report for signing once the data is fully prepared and ready to be signed.</p><p>The procedure for signing a Further Record report and a Daily Report is the same:</p><ul><li><p>Select <strong>Download for electronic signing</strong> via <strong>More Options</strong>, or click the <strong>Download</strong> button. The application generates the report in PDF format, if it does not already exist, or downloads the existing report. At the same time, the record or day is locked with a so-called temporary lock, indicated by a yellow color and a lock icon. The lock prevents all users from making any changes.<img src="'+s+'" alt="" width="600" loading="lazy"><img src="'+l+'" alt="" width="600" loading="lazy"></p></li><li><p>Open the file in Adobe Acrobat Reader DC, where you can review and sign it. Click the signature field marked with a red border.<img src="'+d+'" alt="" width="1000" loading="lazy"></p></li><li><p>A window displaying the available certificates opens. Select the appropriate certificate.<img src="'+p+'" alt="" width="600" loading="lazy"></p></li><li><p>If you do not have a certificate, you can create one by selecting <strong>Configure New Digital ID</strong>. A wizard will guide you through the creation process. In the next step, you can select or modify the appearance of the signature and then click <strong>Sign</strong> to sign the document.</p></li><li><p>Acrobat Reader will prompt you to save the file. We recommend creating a dedicated folder specifically for this purpose and saving the files there.<img src="'+c+'" alt="" width="600" loading="lazy"></p></li></ul><p>The signed file displays a visual representation of the signature. You can view details of the electronic signature by double-clicking this signature mark.</p><ul><li>Upload the signed file back to Buildary by selecting <strong>Upload electronically signed file</strong> via <strong>More Options</strong>, or by clicking the <strong>Upload</strong> button.<img src="'+g+'" alt="" width="800" loading="lazy"></li></ul><p>If you complete all the steps within the time limit configured for the diary, the file is saved and the record or day is permanently locked, meaning that the underline changes to green.<img src="'+h+'" alt="" width="800" loading="lazy"></p><p>Other users can subsequently sign the report using the same procedure described above.</p>',10)])])}const x=t(u,[["render",y]]);export{k as __pageData,x as default};
